// frontend/src/components/WatchListItem.js
import React, { useState, useContext } from "react";
import { Tooltip, Grow } from "@mui/material";
import {
  BarChartOutlined,
  MoreHoriz,
  KeyboardArrowUp,
  KeyboardArrowDown,
} from "@mui/icons-material";
import GeneralContext from "./GeneralContext";

const WatchListItem = ({ stock }) => {
  const [hover, setHover] = useState(false);
  const { openBuyWindow } = useContext(GeneralContext);

  return (
    <li
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}>
      <div className="item">
        <p className={stock.changePct < 0 ? "down" : "up"}>{stock.name}</p>
        <div className="itemInfo">
          <span className="percent">{stock.changePct}%</span>
          {stock.changePct < 0 ? (
            <KeyboardArrowDown className="down" />
          ) : (
            <KeyboardArrowUp className="up" />
          )}
          <span className="price">₹{stock.price}</span>
        </div>
      </div>
      {hover && (
        <span className="actions">
          <Tooltip title="Buy" placement="top" arrow TransitionComponent={Grow}>
            <button
              className="buy"
              onClick={() => openBuyWindow(stock.symbol, "BUY")}>
              Buy
            </button>
          </Tooltip>
          <Tooltip
            title="Sell"
            placement="top"
            arrow
            TransitionComponent={Grow}>
            <button
              className="sell"
              onClick={() => openBuyWindow(stock.symbol, "SELL")}>
              Sell
            </button>
          </Tooltip>
          <Tooltip
            title="Analytics"
            placement="top"
            arrow
            TransitionComponent={Grow}>
            <button className="action">
              <BarChartOutlined className="icon" />
            </button>
          </Tooltip>
          <Tooltip
            title="More"
            placement="top"
            arrow
            TransitionComponent={Grow}>
            <button className="action">
              <MoreHoriz className="icon" />
            </button>
          </Tooltip>
        </span>
      )}
    </li>
  );
};

export default WatchListItem;
